<?php
function EventController(string $resource, ?int $id, array $part, string $method):void {
if($resource==='events'){
  if($method==='GET'&&$id===null){
   $page=max(1,(int)($_GET['page']??1));$size=min(30,max(1,(int)($_GET['limit']??10)));$where=[];$bind=[];
   if(isset($_GET['search'])&&$_GET['search']!==''){$where[]='e.title LIKE ?';$bind[]='%'.$_GET['search'].'%';}
   if(isset($_GET['status'])&&in_array($_GET['status'],['draft','published','cancelled'],true)){$where[]='e.status=?';$bind[]=$_GET['status'];}
   $u=currentUser(false);if(!$u||$u['role']==='customer')$where[]="e.status='published'";
   $sql='SELECT e.*,v.name AS venue_name,(e.total_tickets-(SELECT COALESCE(SUM(quantity),0) FROM bookings b WHERE b.event_id=e.id AND b.status="confirmed")) AS available FROM events e JOIN venues v ON v.id=e.venue_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY e.event_date ASC LIMIT '.$size.' OFFSET '.(($page-1)*$size);
   $s=db()->prepare($sql);$s->execute($bind);reply(200,['page'=>$page,'limit'=>$size,'data'=>$s->fetchAll()]);
  }
  if($method==='GET'&&$id!==null){$event=getEvent($id);need((bool)$event,'Event not found',404);if($event['status']!=='published'){$u=currentUser();need(allowedEvent($event,$u),'Access denied',403);}reply(200,$event);}
  if($method==='POST'){$u=roles(['admin','organiser']);$d=body();requireFields($d,['title','venue_id','event_date','total_tickets','ticket_price']);need(positive($d['venue_id'])&&positive($d['total_tickets'])&&is_numeric($d['ticket_price'])&&(float)$d['ticket_price']>=0,'Invalid event data');need(strtotime($d['event_date'])!==false,'Invalid date');$venue=db()->prepare('SELECT capacity FROM venues WHERE id=?');$venue->execute([$d['venue_id']]);$cap=$venue->fetchColumn();need($cap!==false,'Venue not found',404);need((int)$d['total_tickets']<=(int)$cap,'Tickets exceed venue capacity');$status=$d['status']??'published';need(in_array($status,['draft','published','cancelled'],true),'Invalid status');$s=db()->prepare('INSERT INTO events(title,description,venue_id,organiser_id,event_date,ticket_price,total_tickets,status) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$d['title'],$d['description']??'',(int)$d['venue_id'],$u['id'],$d['event_date'],$d['ticket_price'],$d['total_tickets'],$status]);reply(201,['id'=>(int)db()->lastInsertId()]);}
  if(in_array($method,['PUT','PATCH'],true)&&$id!==null){$u=roles(['admin','organiser']);$event=getEvent($id);need((bool)$event,'Event not found',404);need(allowedEvent($event,$u),'Access denied',403);$d=body();requireFields($d,['title','description','venue_id','event_date','ticket_price','total_tickets','status']);need(positive($d['venue_id'])&&positive($d['total_tickets'])&&is_numeric($d['ticket_price'])&&(float)$d['ticket_price']>=0,'Invalid values');need(in_array($d['status'],['draft','published','cancelled'],true),'Invalid status');need((int)$d['total_tickets']>=(int)$event['sold'],'Cannot set tickets below sold count');$s=db()->prepare('SELECT capacity FROM venues WHERE id=?');$s->execute([$d['venue_id']]);$cap=$s->fetchColumn();need($cap!==false,'Venue not found',404);need($d['total_tickets']<=$cap,'Exceeds venue capacity');$s=db()->prepare('UPDATE events SET title=?,description=?,venue_id=?,event_date=?,ticket_price=?,total_tickets=?,status=? WHERE id=?');$s->execute([$d['title'],$d['description'],$d['venue_id'],$d['event_date'],$d['ticket_price'],$d['total_tickets'],$d['status'],$id]);reply(200,['message'=>'Event updated']);}
  if($method==='DELETE'&&$id!==null){$u=roles(['admin','organiser']);$event=getEvent($id);need((bool)$event,'Event not found',404);need(allowedEvent($event,$u),'Access denied',403);$s=db()->prepare('DELETE FROM events WHERE id=?');$s->execute([$id]);reply(200,['message'=>'Event deleted']);}
 }
}
